FALLBACK = "Reference & Knowledge"


def base_slug(slug):
    return slug[:-10] if slug.endswith("-signature") else slug


def theme_of(db):
    toks = set(base_slug(db["slug"]).split("-"))
    for theme, kws in THEMES:
        if toks & kws:
            return theme
    toks2 = set(re.findall(r"[a-z]+", (db.get("name") or "").lower()))
    toks2.discard("database")
    toks2.discard("databases")
    for theme, kws in THEMES:
        if toks2 & kws:
            return theme
    return FALLBACK
